<template>
	<view class="page">
		<view class="tabs">
			<view :class="['tab', range==='-1d'?'active':'']" @click="changeRange('-1d')">日</view>
			<view :class="['tab', range==='-7d'?'active':'']" @click="changeRange('-7d')">周</view>
			<view :class="['tab', range==='-30d'?'active':'']" @click="changeRange('-30d')">月</view>
			<view :class="['tab', range==='-365d'?'active':'']" @click="changeRange('-365d')">年</view>
		</view>
		<view class="chart-box">
			<qiun-data-charts type="line" :chartData="chartData" :opts="chartOpts" />
		</view>
		<view class="stats">
			<view class="stat">平均值：{{ avg }} {{ unit }}</view>
			<view class="stat">最大值：{{ max }} {{ unit }}</view>
			<view class="stat">最小值：{{ min }} {{ unit }}</view>
		</view>
	</view>
</template>

<script>
	import uCharts from '@/uni_modules/qiun-data-charts/components/qiun-data-charts/qiun-data-charts.vue'
	export default {
		components:{ 'qiun-data-charts': uCharts },
		data(){
			return{
				userId:'',
				field:'',
				range:'-365d',
				chartData:{ categories:[], series:[{name:'', data:[]} ] },
				chartOpts:{
					legend:{show:false},
					xAxis:{disableGrid:false},
					yAxis:{disableGrid:false},
					dataLabel:false,
					extra:{line:{type:'curve'}}
				},
				avg:0, max:0, min:0, unit:'',
				apiBase:'http://10.188.124.8:3000'
			}
		},
		onLoad(query){
			this.userId = query.user_id || ''
			this.field = query.field || 'heart_rate'
			this.setTitle()
			this.fetchData()
		},
		methods:{
			setTitle(){
				const map={ heart_rate:'心率', temperature:'体温', blood_oxygen:'血氧饱和度' }
				uni.setNavigationBarTitle({ title: `${map[this.field]||'趋势'}` })
				this.unit = this.field==='heart_rate'? 'bpm' : (this.field==='temperature'?'℃':'%')
			},
			changeRange(r){ this.range=r; this.fetchData() },
			async fetchData(){
				try{
					const body={ user_id:this.userId, time_range:this.range, fields:this.field }
					const [err, res] = await uni.request({ url:`${this.apiBase}/api/health/user`, method:'POST', data: body, header:{'Content-Type':'application/json'} })
					if(err) return
					let arr=[]; const d=res.data||{}
					if(Array.isArray(d.user_data)) arr=d.user_data
					else if(d.user_data) arr=[d.user_data]
					// 仅保留目标字段
					const fArr = arr.filter(i=> (i.field||i.filed)===this.field)
					// 按时间排序
					const ts = r=> r.timestamp||r.datetime||r.record_time||''
					fArr.sort((a,b)=> new Date(ts(a))-new Date(ts(b)))
					const labels = fArr.map(i=>{
						const t = new Date(ts(i))
						return `${t.getMonth()+1}/${t.getDate()}`
					})
					const values = fArr.map(i=> Number(i.value))
					this.chartData = { categories: labels, series:[{ name:'', data: values }] }
					if(values.length>0){
						const sum = values.reduce((s,v)=>s+v,0)
						this.avg = (sum/values.length).toFixed(2)
						this.max = Math.max(...values).toFixed(2)
						this.min = Math.min(...values).toFixed(2)
					}else{ this.avg=0; this.max=0; this.min=0 }
				}catch(e){}
			}
		}
	}
</script>

<style>
	.page{ padding: 24rpx; background:#FFFFFF; }
	.tabs{ display:flex; gap:20rpx; margin-bottom: 20rpx; }
	.tab{ padding: 10rpx 20rpx; border-radius: 999rpx; background:#F4F5F7; color:#333333; font-size: 26rpx; }
	.tab.active{ background:#2E7CF6; color:#FFFFFF; }
	.chart-box{ background:#FFFFFF; border-radius: 16rpx; padding: 12rpx; }
	.stats{ margin-top: 20rpx; color:#555; font-size: 26rpx; display:flex; gap: 24rpx; }
</style>

